import sys


def z_function(s):
    """返回 z 数组。z[0] = 0（惯例），z[i] 为 s[i:] 与 s 的最长公共前缀长度。"""
    n = len(s)
    z = [0] * n
    l = 0
    r = 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l = i
            r = i + z[i]
    return z


def main():
    s = sys.stdin.readline().strip()
    print(" ".join(map(str, z_function(s))))


if __name__ == "__main__":
    main()

