#include <bits/stdc++.h>
using namespace std;

// 倍增 + sort，O(n log^2 n)。sa[i] 为第 i 小的后缀起始下标（0-based）
vector<int> suffix_array(const string &s) {
    int n = (int)s.size();
    vector<int> sa(n), rankv(n), tmp(n);
    for (int i = 0; i < n; ++i) {
        sa[i] = i;
        rankv[i] = (unsigned char)s[i];
    }
    for (int k = 1; k < n; k *= 2) {
        auto key = [&](int i) {
            int second = (i + k < n) ? rankv[i + k] : -1;
            return pair<int, int>(rankv[i], second);
        };
        sort(sa.begin(), sa.end(), [&](int a, int b) { return key(a) < key(b); });
        tmp[sa[0]] = 0;
        for (int i = 1; i < n; ++i) {
            tmp[sa[i]] = tmp[sa[i - 1]] + (key(sa[i - 1]) < key(sa[i]) ? 1 : 0);
        }
        rankv = tmp;
        if (rankv[sa[n - 1]] == n - 1) break;
    }
    return sa;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string s;
    if (!(cin >> s)) return 0;
    auto sa = suffix_array(s);
    for (int i = 0; i < (int)sa.size(); ++i) {
        if (i) cout << ' ';
        cout << sa[i];
    }
    cout << '\n';
    return 0;
}

