import sys
from collections import deque


class ACAutomaton:
    """多模式串匹配。只支持小写字母。"""

    def __init__(self):
        self.next = [[-1] * 26]
        self.fail = [0]
        self.out = [[]]
        self.order = []      # BFS 序，用于出现次数的反向累加
        self.pat_node = []   # pid -> 终止节点

    def add(self, word, pid):
        node = 0
        for ch in word:
            c = ord(ch) - 97
            if self.next[node][c] == -1:
                self.next[node][c] = len(self.next)
                self.next.append([-1] * 26)
                self.fail.append(0)
                self.out.append([])
            node = self.next[node][c]
        self.out[node].append(pid)
        while len(self.pat_node) <= pid:
            self.pat_node.append(0)
        self.pat_node[pid] = node

    def build(self):
        q = deque()
        for c in range(26):
            v = self.next[0][c]
            if v != -1:
                self.fail[v] = 0
                q.append(v)
                self.order.append(v)
            else:
                self.next[0][c] = 0
        while q:
            u = q.popleft()
            for c in range(26):
                v = self.next[u][c]
                if v != -1:
                    self.fail[v] = self.next[self.fail[u]][c]
                    q.append(v)
                    self.order.append(v)
                else:
                    self.next[u][c] = self.next[self.fail[u]][c]

    def count_each(self, text, m):
        """返回每个模式串在 text 中的出现次数（含重叠）。"""
        cnt = [0] * len(self.next)
        node = 0
        for ch in text:
            node = self.next[node][ord(ch) - 97]
            cnt[node] += 1
        for u in reversed(self.order):
            cnt[self.fail[u]] += cnt[u]
        ans = [0] * m
        for pid in range(m):
            ans[pid] = cnt[self.pat_node[pid]]
        return ans


def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    pats = data[1:1 + n]
    text = data[1 + n]
    ac = ACAutomaton()
    for i, p in enumerate(pats):
        ac.add(p, i)
    ac.build()
    print("\n".join(map(str, ac.count_each(text, n))))


if __name__ == "__main__":
    main()

