#include <bits/stdc++.h>
using namespace std;

struct ACAutomaton {
    // 只支持小写字母
    vector<array<int, 26>> next;
    vector<int> fail;
    vector<vector<int>> out;
    vector<int> order;     // BFS 序，用于出现次数的反向累加
    vector<int> pat_node;  // pid -> 终止节点

    ACAutomaton() {
        next.push_back({});
        next[0].fill(-1);
        fail.push_back(0);
        out.emplace_back();
    }

    void add(const string &word, int pid) {
        int node = 0;
        for (char ch : word) {
            int c = ch - 'a';
            if (next[node][c] == -1) {
                next[node][c] = (int)next.size();
                next.push_back({});
                next.back().fill(-1);
                fail.push_back(0);
                out.emplace_back();
            }
            node = next[node][c];
        }
        out[node].push_back(pid);
        if ((int)pat_node.size() <= pid) pat_node.resize(pid + 1);
        pat_node[pid] = node;
    }

    void build() {
        queue<int> q;
        for (int c = 0; c < 26; ++c) {
            int v = next[0][c];
            if (v != -1) {
                fail[v] = 0;
                q.push(v);
                order.push_back(v);
            } else {
                next[0][c] = 0;
            }
        }
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int c = 0; c < 26; ++c) {
                int v = next[u][c];
                if (v != -1) {
                    fail[v] = next[fail[u]][c];
                    q.push(v);
                    order.push_back(v);
                } else {
                    next[u][c] = next[fail[u]][c];
                }
            }
        }
    }

    // 返回每个模式串在 text 中的出现次数（含重叠）
    vector<long long> count_each(const string &text, int m) {
        vector<long long> cnt(next.size(), 0);
        int node = 0;
        for (char ch : text) {
            node = next[node][ch - 'a'];
            cnt[node] += 1;
        }
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            int u = order[i];
            cnt[fail[u]] += cnt[u];
        }
        vector<long long> ans(m, 0);
        for (int pid = 0; pid < m; ++pid) ans[pid] = cnt[pat_node[pid]];
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<string> pats(n);
    for (int i = 0; i < n; ++i) cin >> pats[i];
    string text;
    cin >> text;
    ACAutomaton ac;
    for (int i = 0; i < n; ++i) ac.add(pats[i], i);
    ac.build();
    auto ans = ac.count_each(text, n);
    for (int i = 0; i < n; ++i) cout << ans[i] << '\n';
    return 0;
}

