import sys


class XorTrie:
    def __init__(self, bits=30):
        self.bits = bits
        self.child = [[-1, -1]]

    def insert(self, x):
        node = 0
        for b in range(self.bits, -1, -1):
            bit = (x >> b) & 1
            if self.child[node][bit] == -1:
                self.child[node][bit] = len(self.child)
                self.child.append([-1, -1])
            node = self.child[node][bit]

    def max_xor(self, x):
        node = 0
        res = 0
        for b in range(self.bits, -1, -1):
            bit = (x >> b) & 1
            want = bit ^ 1
            if self.child[node][want] != -1:
                res |= (1 << b)
                node = self.child[node][want]
            else:
                node = self.child[node][bit]
        return res


def main():
    data = list(map(int, sys.stdin.read().split()))
    n = data[0]
    nums = data[1:1 + n]
    trie = XorTrie()
    for x in nums:
        trie.insert(x)
    print(max(trie.max_xor(x) for x in nums))


if __name__ == "__main__":
    main()

