#include <bits/stdc++.h>
using namespace std;

struct XorTrie {
    int bits;
    vector<array<int, 2>> child;
    XorTrie(int b = 30) : bits(b) {
        child.push_back({-1, -1});
    }
    void insert(int x) {
        int node = 0;
        for (int b = bits; b >= 0; --b) {
            int bit = (x >> b) & 1;
            if (child[node][bit] == -1) {
                child[node][bit] = (int)child.size();
                child.push_back({-1, -1});
            }
            node = child[node][bit];
        }
    }
    int max_xor(int x) const {
        int node = 0;
        int res = 0;
        for (int b = bits; b >= 0; --b) {
            int bit = (x >> b) & 1;
            int want = bit ^ 1;
            if (child[node][want] != -1) {
                res |= (1 << b);
                node = child[node][want];
            } else {
                node = child[node][bit];
            }
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    XorTrie trie;
    for (int x : a) trie.insert(x);
    int ans = 0;
    for (int x : a) ans = max(ans, trie.max_xor(x));
    cout << ans << '\n';
    return 0;
}

