import sys


class MinStack:
    def __init__(self):
        self.data = []
        self.mins = []

    def push(self, x):
        self.data.append(x)
        if not self.mins or x <= self.mins[-1]:
            self.mins.append(x)
        else:
            self.mins.append(self.mins[-1])

    def pop(self):
        self.data.pop()
        self.mins.pop()

    def top(self):
        return self.data[-1]

    def get_min(self):
        return self.mins[-1]


def main():
    lines = sys.stdin.read().strip().split("\n")
    q = int(lines[0])
    st = MinStack()
    out = []
    for i in range(1, q + 1):
        parts = lines[i].split()
        if parts[0] == "push":
            st.push(int(parts[1]))
        elif parts[0] == "pop":
            st.pop()
        elif parts[0] == "top":
            out.append(str(st.top()))
        elif parts[0] == "getMin":
            out.append(str(st.get_min()))
    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

