import sys
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.d = OrderedDict()

    def get(self, key):
        if key not in self.d:
            return -1
        self.d.move_to_end(key)
        return self.d[key]

    def put(self, key, value):
        if key in self.d:
            self.d.move_to_end(key)
        self.d[key] = value
        if len(self.d) > self.cap:
            self.d.popitem(last=False)


def main():
    lines = sys.stdin.read().strip().split("\n")
    cap = int(lines[0])
    q = int(lines[1])
    cache = LRUCache(cap)
    out = []
    for i in range(2, 2 + q):
        parts = lines[i].split()
        if parts[0] == "put":
            cache.put(int(parts[1]), int(parts[2]))
        else:
            out.append(str(cache.get(int(parts[1]))))
    sys.stdout.write("\n".join(out))


if __name__ == "__main__":
    main()

template_cpp:
#include <bits/stdc++.h>
using namespace std;

struct Node {
    int key, val;
};

class LRUCache {
    int cap;
    list<Node> lst;  // 头 = 最近使用
    unordered_map<int, list<Node>::iterator> mp;

public:
    LRUCache(int capacity) : cap(capacity) {}

    int get(int key) {
        auto it = mp.find(key);
        if (it == mp.end()) return -1;
        lst.splice(lst.begin(), lst, it->second);
        return it->second->val;
    }

    void put(int key, int value) {
        auto it = mp.find(key);
        if (it != mp.end()) {
            it->second->val = value;
            lst.splice(lst.begin(), lst, it->second);
            return;
        }
        if ((int)lst.size() == cap) {
            mp.erase(lst.back().key);
            lst.pop_back();
        }
        lst.push_front({key, value});
        mp[key] = lst.begin();
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int cap, q;
    if (!(cin >> cap)) return 0;
    cin >> q;
    LRUCache cache(cap);
    while (q--) {
        string op;
        cin >> op;
        if (op == "put") {
            int k, v;
            cin >> k >> v;
            cache.put(k, v);
        } else {
            int k;
            cin >> k;
            cout << cache.get(k) << '\n';
        }
    }
    return 0;
}

