#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200000;

int n, q;
long long a[MAXN + 5];
long long tree[MAXN * 4 + 5];
long long lazy_[MAXN * 4 + 5];

void build(int node, int l, int r) {
    if (l == r) {
        tree[node] = a[l];
        return;
    }
    int mid = (l + r) / 2;
    build(node * 2, l, mid);
    build(node * 2 + 1, mid + 1, r);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

void apply(int node, int l, int r, long long v) {
    tree[node] += v * (r - l + 1);
    lazy_[node] += v;
}

void push(int node, int l, int r) {
    if (lazy_[node] != 0 && l != r) {
        int mid = (l + r) / 2;
        apply(node * 2, l, mid, lazy_[node]);
        apply(node * 2 + 1, mid + 1, r, lazy_[node]);
        lazy_[node] = 0;
    }
}

void seg_add(int node, int l, int r, int ql, int qr, long long v) {
    if (ql <= l && r <= qr) {
        apply(node, l, r, v);
        return;
    }
    push(node, l, r);
    int mid = (l + r) / 2;
    if (ql <= mid) {
        seg_add(node * 2, l, mid, ql, qr, v);
    }
    if (qr > mid) {
        seg_add(node * 2 + 1, mid + 1, r, ql, qr, v);
    }
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

long long seg_sum(int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[node];
    }
    push(node, l, r);
    int mid = (l + r) / 2;
    long long res = 0;
    if (ql <= mid) {
        res += seg_sum(node * 2, l, mid, ql, qr);
    }
    if (qr > mid) {
        res += seg_sum(node * 2 + 1, mid + 1, r, ql, qr);
    }
    return res;
}

