        int t, l, r;
        cin >> t >> l >> r;
        if (t == 1) {
            long long x;
            cin >> x;
            seg_add(1, 1, n, l, r, x);
        } else {
            cout << seg_sum(1, 1, n, l, r) << '\n';
        }
    }
    return 0;
}

