    }
    int end_l = (bl + 1) * B;
    for (int i = l; i <= end_l; i++) {
        a[i] += v;
        block_sum[bl] += v;
    }
    for (int b = bl + 1; b < br; b++) {
        block_add[b] += v;
        block_sum[b] += v * B;
    }
    int start_r = br * B + 1;
    for (int i = start_r; i <= r; i++) {
        a[i] += v;
        block_sum[br] += v;
    }
}

long long range_sum(int l, int r) {
    int bl = (l - 1) / B;
    int br = (r - 1) / B;
    long long res = 0;
    if (bl == br) {
        for (int i = l; i <= r; i++) {
            res += a[i] + block_add[bl];
        }
        return res;
    }
    int end_l = (bl + 1) * B;
    for (int i = l; i <= end_l; i++) {
        res += a[i] + block_add[bl];
    }
    for (int b = bl + 1; b < br; b++) {
        res += block_sum[b];
    }
    int start_r = br * B + 1;
    for (int i = start_r; i <= r; i++) {
        res += a[i] + block_add[br];
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n >> q)) {
        return 0;
    }
    a.assign(n + 1, 0);
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    B = (int)sqrt(n) + 1;
    int nb = (n + B - 1) / B;
    block_sum.assign(nb, 0);
    block_add.assign(nb, 0);
    for (int i = 1; i <= n; i++) {
        block_sum[(i - 1) / B] += a[i];
    }
    for (int i = 0; i < q; i++) {
        int t, l, r;
        cin >> t >> l >> r;
        if (t == 1) {
            long long x;
            cin >> x;
            range_add(l, r, x);
        } else {
            cout << range_sum(l, r) << '\n';
        }
    }
    return 0;
}

