struct Query {
    int l, r, idx, block;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) {
        return 0;
    }
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    // 离散化，方便用数组做计数器
    vector<int> vals = a;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    for (int i = 0; i < n; i++) {
        a[i] = (int)(lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin());
    }
    int B = q == 0 ? (int)sqrt(n) + 1 : n / (int)sqrt(q) + 1;
    vector<Query> qs(q);
    for (int i = 0; i < q; i++) {
        int l, r;
        cin >> l >> r;
        --l;
        --r;
        qs[i] = {l, r, i, l / B};
    }
    sort(qs.begin(), qs.end(), [](const Query &x, const Query &y) {
        if (x.block != y.block) {
            return x.block < y.block;
        }
        if (x.block % 2 == 0) {
            return x.r < y.r;
        }
        return x.r > y.r;
    });
    vector<int> cnt(vals.size(), 0);
    vector<int> ans(q);
    int distinct = 0;
    int cur_l = 0, cur_r = -1;
    auto add = [&](int pos) {
        if (cnt[a[pos]] == 0) {
            distinct++;
        }
        cnt[a[pos]]++;
    };
    auto remove = [&](int pos) {
        cnt[a[pos]]--;
        if (cnt[a[pos]] == 0) {
            distinct--;
        }
    };
    for (auto &qu : qs) {
        while (cur_l > qu.l) {
            cur_l--;
            add(cur_l);
        }
        while (cur_r < qu.r) {
            cur_r++;
            add(cur_r);
        }
        while (cur_l < qu.l) {
            remove(cur_l);
            cur_l++;
        }
        while (cur_r > qu.r) {
            remove(cur_r);
            cur_r--;
        }
        ans[qu.idx] = distinct;
    }
    for (int i = 0; i < q; i++) {
        cout << ans[i] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;
const int MAXNODE = MAXN * 20;

int ls[MAXNODE], rs[MAXNODE], sumv[MAXNODE];
int tot = 0;
int roots[MAXN];

int clone_node(int node) {
    ++tot;
    ls[tot] = ls[node];
    rs[tot] = rs[node];
    sumv[tot] = sumv[node];
    return tot;
}

int update(int prev, int l, int r, int p) {
    int node = clone_node(prev);
    sumv[node]++;
    if (l != r) {
        int mid = (l + r) / 2;
        if (p <= mid) {
            ls[node] = update(ls[prev], l, mid, p);
        } else {
            rs[node] = update(rs[prev], mid + 1, r, p);
        }
    }
    return node;
}

int kth(int u, int v, int l, int r, int k) {
    // 在版本 v 减去版本 u 的区间里找第 k 小
    if (l == r) {
        return l;
    }
    int mid = (l + r) / 2;
    int left_count = sumv[ls[v]] - sumv[ls[u]];
    if (k <= left_count) {
        return kth(ls[u], ls[v], l, mid, k);
    }
    return kth(rs[u], rs[v], mid + 1, r, k - left_count);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    if (!(cin >> n >> q)) {
        return 0;
    }
    vector<int> a(n + 1);
    vector<int> vals;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
        vals.push_back(a[i]);
    }
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());
    int m = (int)vals.size();
    roots[0] = 0;
    for (int i = 1; i <= n; i++) {
        int p = (int)(lower_bound(vals.begin(), vals.end(), a[i]) - vals.begin()) + 1;
        roots[i] = update(roots[i - 1], 1, m, p);
    }
    for (int i = 0; i < q; i++) {
        int l, r, k;
        cin >> l >> r >> k;
        int idx = kth(roots[l - 1], roots[r], 1, m, k);
        cout << vals[idx - 1] << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;

int n;
vector<int> g[MAXN];
long long init_val[MAXN];
int parent_[MAXN], depth_[MAXN], heavy[MAXN], head[MAXN], pos[MAXN], sz[MAXN];
int timer_ = 0;
long long arr_[MAXN];
long long tree[MAXN * 4], lazy_[MAXN * 4];

void dfs1(int u, int p) {
    parent_[u] = p;
    sz[u] = 1;
    int max_sz = 0;
    for (int v : g[u]) {
        if (v == p) {
            continue;
        }
        depth_[v] = depth_[u] + 1;
        dfs1(v, u);
        sz[u] += sz[v];
        if (sz[v] > max_sz) {
            max_sz = sz[v];
            heavy[u] = v;
        }
    }
}

void dfs2(int u, int h) {
    head[u] = h;
    pos[u] = ++timer_;
    if (heavy[u]) {
        dfs2(heavy[u], h);
    }
    for (int v : g[u]) {
        if (v != parent_[u] && v != heavy[u]) {
            dfs2(v, v);
        }
    }
}

void build(int node, int l, int r) {
    if (l == r) {
        tree[node] = arr_[l];
        return;
    }
    int mid = (l + r) / 2;
    build(node * 2, l, mid);
    build(node * 2 + 1, mid + 1, r);
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

void apply(int node, int l, int r, long long v) {
    tree[node] += v * (r - l + 1);
    lazy_[node] += v;
}

void push(int node, int l, int r) {
    if (lazy_[node] != 0 && l != r) {
        int mid = (l + r) / 2;
        apply(node * 2, l, mid, lazy_[node]);
        apply(node * 2 + 1, mid + 1, r, lazy_[node]);
        lazy_[node] = 0;
    }
}

void seg_add(int node, int l, int r, int ql, int qr, long long v) {
    if (ql <= l && r <= qr) {
        apply(node, l, r, v);
        return;
    }
    push(node, l, r);
    int mid = (l + r) / 2;
    if (ql <= mid) {
        seg_add(node * 2, l, mid, ql, qr, v);
    }
    if (qr > mid) {
        seg_add(node * 2 + 1, mid + 1, r, ql, qr, v);
    }
    tree[node] = tree[node * 2] + tree[node * 2 + 1];
}

long long seg_sum(int node, int l, int r, int ql, int qr) {
    if (ql <= l && r <= qr) {
        return tree[node];
    }
    push(node, l, r);
    int mid = (l + r) / 2;
    long long res = 0;
    if (ql <= mid) {
        res += seg_sum(node * 2, l, mid, ql, qr);
    }
    if (qr > mid) {
        res += seg_sum(node * 2 + 1, mid + 1, r, ql, qr);
    }
    return res;
}

void path_add(int u, int v, long long x) {
    while (head[u] != head[v]) {
        if (depth_[head[u]] < depth_[head[v]]) {
            swap(u, v);
        }
        seg_add(1, 1, n, pos[head[u]], pos[u], x);
        u = parent_[head[u]];
    }
    if (depth_[u] > depth_[v]) {
        swap(u, v);
    }
    seg_add(1, 1, n, pos[u], pos[v], x);
}

long long path_sum(int u, int v) {
    long long res = 0;
    while (head[u] != head[v]) {
        if (depth_[head[u]] < depth_[head[v]]) {
            swap(u, v);
        }
        res += seg_sum(1, 1, n, pos[head[u]], pos[u]);
        u = parent_[head[u]];
    }
    if (depth_[u] > depth_[v]) {
        swap(u, v);
    }
    res += seg_sum(1, 1, n, pos[u], pos[v]);
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (!(cin >> n)) {
        return 0;
    }
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    for (int i = 1; i <= n; i++) {
        cin >> init_val[i];
    }
    depth_[1] = 0;
    dfs1(1, 0);
    dfs2(1, 1);
    for (int i = 1; i <= n; i++) {
        arr_[pos[i]] = init_val[i];
    }
    build(1, 1, n);
    int qq;
    cin >> qq;
    for (int i = 0; i < qq; i++) {
        int t, u, v;
        cin >> t >> u >> v;
        if (t == 1) {
            long long x;
            cin >> x;
            path_add(u, v, x);
        } else {
            cout << path_sum(u, v) << '\n';
        }
    }
    return 0;
}

