        int t, a, b;
        cin >> t >> a >> b;
        if (t == 1) {
            long long w;
            cin >> w;
            int ra = find_root(a);
            int rb = find_root(b);
            if (ra != rb) {
                // 断言 dist[b] - dist[a] = w，把 ra 挂到 rb 下
                parent_[ra] = rb;
                dist_[ra] = dist_[b] - dist_[a] - w;
            }
        } else {
            int ra = find_root(a);
            int rb = find_root(b);
            if (ra != rb) {
                cout << "Unknown\n";
            } else {
                cout << dist_[b] - dist_[a] << '\n';
            }
        }
    }
    return 0;
}

