import sys
from collections import deque

sys.setrecursionlimit(10 ** 6)


def build(level):
    '''层序数组建树，-1 表示空。返回根节点 [值, 左, 右]。'''
    nodes = [None if v == -1 else [v, None, None] for v in level]
    for i, nd in enumerate(nodes):
        if nd is None:
            continue
        l, r = 2 * i + 1, 2 * i + 2
        if l < len(nodes):
            nd[1] = nodes[l]
        if r < len(nodes):
            nd[2] = nodes[r]
    return nodes[0] if nodes else None


def serialize(root):
    '''层序序列化：空节点记 #，末尾多余的 # 去掉。'''
    if root is None:
        return ''
    out = []
    q = deque([root])
    while q:
        nd = q.popleft()
        if nd is None:
            out.append('#')
        else:
            out.append(str(nd[0]))
            q.append(nd[1])
            q.append(nd[2])
    while out and out[-1] == '#':
        out.pop()
    return ','.join(out)


def deserialize(s):
    '''把 serialize 的格式还原成树。'''
    if not s:
        return None
    vals = s.split(',')
    root = [int(vals[0]), None, None]
    q = deque([root])
    i = 1
    while q and i < len(vals):
        nd = q.popleft()
        for side in (1, 2):
            if i < len(vals) and vals[i] != '#':
                child = [int(vals[i]), None, None]
                nd[side] = child
                q.append(child)
            i += 1
    return root


def preorder(nd, res):
    if nd is None:
        return
    res.append(str(nd[0]))
    preorder(nd[1], res)
    preorder(nd[2], res)


if __name__ == '__main__':
    # 输入：单行层序数组，-1 表空；输出：序列化→反序列化后先序序列
    level = list(map(int, sys.stdin.read().split()))
    root = build(level)
    back = deserialize(serialize(root))
    res = []
    preorder(back, res)
    print(' '.join(res))

