    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    // 输入：n m，接下来 m 行 a b 表示子句 (a OR b)，正数 k 表 xk 为真，负数 -k 表 xk 为假
    int n, m;
    if (!(cin >> n >> m)) return 0;
    // 变量 i(1-based)：假文字 2*(i-1)，真文字 2*(i-1)+1；取反 = xor 1
    N = 2 * n;
    g.assign(N, {});
    auto lit = [&](int x) { return 2 * (abs(x) - 1) + (x > 0 ? 1 : 0); };
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        int la = lit(a), lb = lit(b);
        g[la ^ 1].push_back(lb);  // !a -> b
        g[lb ^ 1].push_back(la);  // !b -> a
    }
    disc_.assign(N, 0);
    low_.assign(N, 0);
    comp_.assign(N, -1);
    on_stack_.assign(N, 0);
    for (int u = 0; u < N; ++u) {
        if (disc_[u] == 0) dfs(u);
    }
    vector<int> val(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        int f = 2 * (i - 1), t = 2 * (i - 1) + 1;
        if (comp_[f] == comp_[t]) {
            cout << "IMPOSSIBLE\n";
            return 0;
        }
        // Tarjan 按逆拓扑顺序给分量编号：假文字的分量编号更大 → 该变量取真
        val[i] = (comp_[f] > comp_[t]) ? 1 : 0;
    }
    cout << "POSSIBLE\n";
    for (int i = 1; i <= n; ++i) {
        if (i > 1) cout << ' ';
        cout << val[i];
    }
    cout << '\n';
    return 0;
}

