    vector<vector<pair<int, int64>>> g(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v;
        int64 w;
        cin >> u >> v >> w;
        g[u].emplace_back(v, w);
        g[v].emplace_back(u, w);
    }
    vector<vector<int64>> dist(n + 1, vector<int64>(k + 1, INF64));
    dist[s][0] = 0;
    using T = tuple<int64, int, int>;  // 距离, 点, 已用免费次数
    priority_queue<T, vector<T>, greater<T>> pq;
    pq.emplace(0, s, 0);
    while (!pq.empty()) {
        auto [d, u, used] = pq.top(); pq.pop();
        if (d != dist[u][used]) continue;
        for (auto [v, w] : g[u]) {
            if (dist[v][used] > d + w) {  // 这条边付费
                dist[v][used] = d + w;
                pq.emplace(d + w, v, used);
            }
            if (used < k && dist[v][used + 1] > d) {  // 这条边免费
                dist[v][used + 1] = d;
                pq.emplace(d, v, used + 1);
            }
        }
    }
    int64 ans = INF64;
    for (int j = 0; j <= k; ++j) ans = min(ans, dist[t][j]);
    cout << ans << '\n';
    return 0;
}

