def bidirectional_bfs(n, s, t, edges):
    '''无向无权图双向 BFS，返回 s 到 t 的最短边数，到不了返回 -1。'''
    from collections import deque
    if s == t:
        return 0
    g = [[] for _ in range(n + 1)]
    for u, v in edges:
        g[u].append(v)
        g[v].append(u)
    dist_s, dist_t = {s: 0}, {t: 0}
    qs, qt = deque([s]), deque([t])
    while qs and qt:
        if len(qs) > len(qt):  # 每次扩展节点数少的一侧
            qs, qt = qt, qs
            dist_s, dist_t = dist_t, dist_s
        for _ in range(len(qs)):
            u = qs.popleft()
            for v in g[u]:
                if v in dist_s:
                    continue
                if v in dist_t:
                    return dist_s[u] + 1 + dist_t[v]
                dist_s[v] = dist_s[u] + 1
                qs.append(v)
    return -1


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    n, m, s, t = data[0], data[1], data[2], data[3]
    edges = [(data[4 + 2 * i], data[5 + 2 * i]) for i in range(m)]
    print(bidirectional_bfs(n, s, t, edges))

