def solve_puzzle(board):
    '''IDA* 解 3x3 八数码。board 为 9 个数（0 为空格），返回最少步数，无解返回 -1。'''
    import sys
    sys.setrecursionlimit(1000000)
    start = tuple(board)

    def manhattan(state):
        d = 0
        for i, v in enumerate(state):
            if v == 0:
                continue
            gi = v - 1
            d += abs(i // 3 - gi // 3) + abs(i % 3 - gi % 3)
        return d

    nbr = []
    for i in range(9):
        x, y = divmod(i, 3)
        cur = []
        if x > 0:
            cur.append(i - 3)
        if x < 2:
            cur.append(i + 3)
        if y > 0:
            cur.append(i - 1)
        if y < 2:
            cur.append(i + 1)
        nbr.append(cur)

    found = []

    def dfs(state, blank, g, bound, prev):
        h = manhattan(state)
        f = g + h
        if f > bound:
            return f
        if h == 0:
            found.append(g)
            return -1
        nxt = 10 ** 9
        lst = list(state)
        for nb in nbr[blank]:
            if nb == prev:  # 不走回头路
                continue
            lst[blank], lst[nb] = lst[nb], lst[blank]
            t = dfs(tuple(lst), nb, g + 1, bound, blank)
            lst[blank], lst[nb] = lst[nb], lst[blank]
            if t == -1:
                return -1
            if t < nxt:
                nxt = t
        return nxt

    bound = manhattan(start)
    while bound <= 40 and not found:
        t = dfs(start, start.index(0), 0, bound, -1)
        if t == -1 or t >= 10 ** 9:
            break
        bound = t
    return found[0] if found else -1


if __name__ == '__main__':
    import sys
    data = list(map(int, sys.stdin.read().split()))
    print(solve_puzzle(data[:9]))

