#include <bits/stdc++.h>
using namespace std;

int manhattan(const array<int, 9> &s) {
    int d = 0;
    for (int i = 0; i < 9; ++i) {
        int v = s[i];
        if (v == 0) continue;
        int gi = v - 1;
        d += abs(i / 3 - gi / 3) + abs(i % 3 - gi % 3);
    }
    return d;
}

int nbr_[9][4];
int nbr_cnt[9];

// 返回 -1 表示找到（答案记在 answer 里），否则返回下一轮的 bound
int dfs(array<int, 9> &s, int blank, int g, int bound, int prev, int &answer) {
    int h = manhattan(s);
    int f = g + h;
    if (f > bound) return f;
    if (h == 0) { answer = g; return -1; }
    int nxt = INT_MAX;
    for (int k = 0; k < nbr_cnt[blank]; ++k) {
        int nb = nbr_[blank][k];
        if (nb == prev) continue;  // 不走回头路
        swap(s[blank], s[nb]);
        int t = dfs(s, nb, g + 1, bound, blank, answer);
        swap(s[blank], s[nb]);
        if (t == -1) return -1;
        nxt = min(nxt, t);
    }
    return nxt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    for (int i = 0; i < 9; ++i) {
        int x = i / 3, y = i % 3, c = 0;
        if (x > 0) nbr_[i][c++] = i - 3;
        if (x < 2) nbr_[i][c++] = i + 3;
        if (y > 0) nbr_[i][c++] = i - 1;
        if (y < 2) nbr_[i][c++] = i + 1;
        nbr_cnt[i] = c;
    }
    array<int, 9> s;
    for (int i = 0; i < 9; ++i) {
        if (!(cin >> s[i])) return 0;
    }
    int blank = 0;
    while (s[blank] != 0) ++blank;
    int answer = -1;
    int bound = manhattan(s);
    while (bound <= 40 && answer < 0) {
        int t = dfs(s, blank, 0, bound, -1, answer);
        if (t == -1 || t == INT_MAX) break;
        bound = t;
    }
    cout << answer << '\n';
    return 0;
}

