    data = list(map(int, sys.stdin.read().split()))
    n, q = data[0], data[1]
    parent = [0] * (n + 1)
    for i in range(2, n + 1):
        parent[i] = data[i]
    queries = [(data[n + 1 + 2 * i], data[n + 2 + 2 * i]) for i in range(q)]
    for ans in kth_ancestor(n, parent, queries):
        print(ans)

