#include <bits/stdc++.h>
using namespace std;

struct Line {
    long long m, b;
    long long at(long long x) const {
        return m * x + b;
    }
};

// 求最小值、斜率递减加入时，l2 是否多余
bool bad(const Line &l1, const Line &l2, const Line &l3) {
    __int128 left = (__int128)(l3.b - l1.b) * (l1.m - l2.m);
    __int128 right = (__int128)(l2.b - l1.b) * (l1.m - l3.m);
    return left <= right;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long C;
    if (!(cin >> n >> C)) {
        return 0;
    }
    vector<long long> a(n + 1);
    for (int i = 1; i <= n; ++i) {
        cin >> a[i];
    }
    // 前缀和；要求 a[i] >= 0，保证斜率单调、查询 x 单调
    vector<long long> s(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        s[i] = s[i - 1] + a[i];
    }
    // dp[i] = C + s[i]^2 + min_j(dp[j] + s[j]^2 - 2*s[i]*s[j])
    const long long INF = (long long)4e18;
    vector<long long> dp(n + 1, INF);
    dp[0] = 0;
    deque<Line> hull;  // 斜率递减
    hull.push_back({0, 0});  // j = 0
    for (int i = 1; i <= n; ++i) {
        while (hull.size() >= 2 && hull[0].at(s[i]) >= hull[1].at(s[i])) {
            hull.pop_front();
        }
        long long best = hull[0].at(s[i]);
        dp[i] = C + s[i] * s[i] + best;
        Line nl = {-2 * s[i], dp[i] + s[i] * s[i]};
        while (hull.size() >= 2 && bad(hull[hull.size() - 2], hull[hull.size() - 1], nl)) {
            hull.pop_back();
        }
        hull.push_back(nl);
    }
    cout << dp[n] << "\n";
    return 0;
}

