// 返回 g = gcd(a, b)，并求出 x, y 使 a*x + b*y = g
int64 exgcd(int64 a, int64 b, int64 &x, int64 &y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    int64 x1, y1;
    int64 g = exgcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int64 mod_inverse(int64 a, int64 mod) {
    a %= mod;
    int64 x, y;
    int64 g = exgcd(a, mod, x, y);
    if (g != 1) {
        return -1;  // 逆元不存在
    }
    x %= mod;
    if (x < 0) {
        x += mod;  // C++ 的 % 对负数得负，要手动转正
    }
    return x;
}

