def mobius_sieve(n):
    """线性筛返回 mu[0..n]，mu[1]=1。"""
    mu = [0] * (n + 1)
    primes = []
    is_comp = [False] * (n + 1)
    mu[1] = 1
    for i in range(2, n + 1):
