    vector<Pt> pts(n);
    for (int i = 0; i < n; ++i) cin >> pts[i].x >> pts[i].y;
    sort(pts.begin(), pts.end());
    pts.erase(unique(pts.begin(), pts.end()), pts.end());
    if (pts.size() <= 1) {
        cout << pts.size() << '\n';
        for (auto &p : pts) cout << p.x << ' ' << p.y << '\n';
        return 0;
    }
    // Andrew 单调链：下凸壳 + 上凸壳，叉积 <= 0 时弹出（删掉边上共线点）
    vector<Pt> lower, upper;
    for (auto &p : pts) {
        while (lower.size() >= 2 && cross(lower[lower.size() - 2], lower.back(), p) <= 0)
            lower.pop_back();
        lower.push_back(p);
    }
    for (int i = (int)pts.size() - 1; i >= 0; --i) {
        auto &p = pts[i];
        while (upper.size() >= 2 && cross(upper[upper.size() - 2], upper.back(), p) <= 0)
            upper.pop_back();
        upper.push_back(p);
    }
    lower.pop_back();
    upper.pop_back();
    cout << lower.size() + upper.size() << '\n';
    for (auto &p : lower) cout << p.x << ' ' << p.y << '\n';
    for (auto &p : upper) cout << p.x << ' ' << p.y << '\n';
    return 0;
}

