import sys


class BIT:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)

    def add(self, i, d):
        while i <= self.n:
            self.t[i] += d
            i += i & -i

    def sum(self, i):
        s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s


def distinct_queries(a, queries):
    """a: 0-indexed 数组；queries: [(l, r)] 1-indexed 闭区间。返回每个询问的不同数。"""
    n = len(a)
    bit = BIT(n)
    last = {}
    order = sorted(range(len(queries)), key=lambda i: queries[i][1])
    ans = [0] * len(queries)
    r = 0
    for qi in order:
        l, qr = queries[qi]
        while r < qr:
            r += 1
            v = a[r - 1]
            if v in last:
                bit.add(last[v], -1)
            bit.add(r, 1)
            last[v] = r
        ans[qi] = bit.sum(qr) - bit.sum(l - 1)
    return ans


if __name__ == '__main__':
    data = list(map(int, sys.stdin.read().split()))
    n, q = data[0], data[1]
    a = data[2:2 + n]
    qs = []
    p = 2 + n
    for _ in range(q):
        qs.append((data[p], data[p + 1]))
        p += 2
    for x in distinct_queries(a, qs):
        print(x)

