struct BIT {
    int n;
    vector<int> t;
    BIT(int n = 0) { init(n); }
    void init(int n_) {
        n = n_;
        t.assign(n + 1, 0);
    }
    void add(int i, int d) {
        for (; i <= n; i += i & -i) t[i] += d;
    }
    int sum(int i) const {
        int s = 0;
        for (; i > 0; i -= i & -i) s += t[i];
        return s;
    }
};

