import sys


def ternary_min(l, r, f):
    """整数域三分求 f 在 [l, r] 上的最小值点。f 需是单谷函数。返回 (x, f(x))。"""
    while r - l > 3:
        m1 = l + (r - l) // 3
        m2 = r - (r - l) // 3
        if f(m1) > f(m2):
            l = m1
        else:
            r = m2
    best = l
    for x in range(l + 1, r + 1):
        if f(x) < f(best):
            best = x
    return best, f(best)


if __name__ == '__main__':
    # 输入: l r；第二行 a b c 表示 f(x) = a*x^2 + b*x + c（a > 0 开口向上）
