    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    if (!(cin >> n)) return 0;
    int64 pref = 0;
    for (int i = 0; i < n; ++i) {
        int64 v;
        cin >> v;
        pref = mod_norm(pref + v);
        cout << pref << (i + 1 == n? '\n': ' ');
    }
    return 0;
}
